sql.where:
owner_id = #{ownerId}

    AND archived = FALSE


    AND LOWER(name) LIKE LOWER(CONCAT('%', #{name}, '%'))

mapper.select:
SELECT COUNT(*)
FROM habits
WHERE owner_id = #{ownerId}
AND id = #{id}

mapper.delete:
DELETE FROM habits
WHERE owner_id = #{ownerId}
AND id = #{id}

mapper.select:
SELECT id, owner_id, version, name, completion_count, archived, longest_streak, current_streak, last_completed_at, created_at, scheduled_days FROM habits
ORDER BY ${orderBy}
LIMIT #{limit} OFFSET #{offset}
